// Shared by TypeORM migrations and the SQL export for MySQL Workbench.
// MySQL 8.0.22+; UUIDs are generated by the application, dates are UTC DATETIME(3).
export const schemaStatements = [
  `CREATE TABLE user_types (
    id CHAR(36) PRIMARY KEY, name VARCHAR(20) NOT NULL UNIQUE,
    CHECK (name IN ('admin','driver','passenger'))
  ) ENGINE=InnoDB`,
  `INSERT INTO user_types(id,name) VALUES (UUID(),'admin'),(UUID(),'driver'),(UUID(),'passenger')`,
  `CREATE TABLE users (
    id CHAR(36) PRIMARY KEY, user_type_id CHAR(36) NOT NULL,
    registration_number VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT false, created_at DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
    FOREIGN KEY (user_type_id) REFERENCES user_types(id)
  ) ENGINE=InnoDB`,
  `CREATE TABLE license_plates (
    id CHAR(36) PRIMARY KEY, plate VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
    is_active BOOLEAN NOT NULL DEFAULT true,
    CHECK (REGEXP_LIKE(plate,'^[A-Z]{3}-[0-9][A-Z0-9][0-9]{2}$','c'))
  ) ENGINE=InnoDB`,
  `CREATE TABLE bus_lines (
    id CHAR(36) PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true
  ) ENGINE=InnoDB`,
  `CREATE TABLE bus_stops (
    id CHAR(36) PRIMARY KEY, short_name VARCHAR(50) NOT NULL, long_name VARCHAR(150) NOT NULL,
    location POINT NOT NULL SRID 4326, is_active BOOLEAN NOT NULL DEFAULT true,
    SPATIAL INDEX bus_stops_geo(location)
  ) ENGINE=InnoDB`,
  `CREATE TABLE driver_sessions (
    id CHAR(36) PRIMARY KEY, driver_id CHAR(36) NOT NULL,
    license_plate VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, bus_line_id CHAR(36) NOT NULL,
    socket_id VARCHAR(100), started_at DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
    last_seen_at DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)), last_sample_at DATETIME(3), closed_at DATETIME(3),
    active_vehicle VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin
      GENERATED ALWAYS AS (IF(closed_at IS NULL,license_plate,NULL)) STORED,
    active_driver CHAR(36) GENERATED ALWAYS AS (IF(closed_at IS NULL,driver_id,NULL)) STORED,
    UNIQUE KEY one_session_per_vehicle(active_vehicle), UNIQUE KEY one_session_per_driver(active_driver),
    INDEX sessions_expiry(closed_at,last_seen_at),
    FOREIGN KEY (driver_id) REFERENCES users(id), FOREIGN KEY (license_plate) REFERENCES license_plates(plate),
    FOREIGN KEY (bus_line_id) REFERENCES bus_lines(id)
  ) ENGINE=InnoDB`,
  `CREATE TABLE bus_locations (
    id CHAR(36) PRIMARY KEY, session_id CHAR(36) NOT NULL,
    license_plate VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    bus_line_id CHAR(36) NOT NULL, driver_id CHAR(36) NOT NULL,
    bus_status VARCHAR(20) NOT NULL CHECK(bus_status IN ('circulating','notCirculating')),
    location POINT NOT NULL SRID 4326, speed DECIMAL(5,2) NOT NULL CHECK(speed BETWEEN 0 AND 80),
    heading_towards DECIMAL(5,2) NOT NULL CHECK(heading_towards >= 0 AND heading_towards < 360),
    timestamp DATETIME(3) NOT NULL, received_at DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
    FOREIGN KEY (session_id) REFERENCES driver_sessions(id), FOREIGN KEY (license_plate) REFERENCES license_plates(plate),
    FOREIGN KEY (bus_line_id) REFERENCES bus_lines(id), FOREIGN KEY (driver_id) REFERENCES users(id),
    INDEX bus_locations_latest(license_plate,timestamp DESC), INDEX bus_locations_session(session_id,timestamp DESC),
    SPATIAL INDEX bus_locations_geo(location)
  ) ENGINE=InnoDB`,
  `CREATE TABLE campus_places (
    id CHAR(36) PRIMARY KEY, name VARCHAR(150) NOT NULL, category VARCHAR(50) NOT NULL,
    location POINT NOT NULL SRID 4326, description TEXT, SPATIAL INDEX campus_places_geo(location)
  ) ENGINE=InnoDB`,
  `CREATE TABLE forum_posts (
    id CHAR(36) PRIMARY KEY, author_id CHAR(36), is_anonymous BOOLEAN NOT NULL DEFAULT false,
    title VARCHAR(255) NOT NULL, content TEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
    FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL, INDEX forum_posts_created(created_at DESC,id)
  ) ENGINE=InnoDB`,
  `CREATE TABLE forum_answers (
    id CHAR(36) PRIMARY KEY, post_id CHAR(36) NOT NULL, author_id CHAR(36),
    is_anonymous BOOLEAN NOT NULL DEFAULT false, content TEXT NOT NULL,
    created_at DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
    FOREIGN KEY (post_id) REFERENCES forum_posts(id) ON DELETE CASCADE,
    FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL, INDEX forum_answers_post(post_id,created_at)
  ) ENGINE=InnoDB`,
];
